begin;
create table if not exists public.ige_grade_patterns (
  mode text not null check (mode in ('abacus','mental')),
  grade integer not null check (grade between 1 and 12),
  pattern jsonb not null,
  primary key(mode,grade)
);
alter table public.ige_grade_patterns enable row level security;
revoke all on public.ige_grade_patterns from public,anon,authenticated;
-- Patterns transcribed from each workbook's first, student-facing paper. The mirrored answer sheet is excluded.
